# Expected values generated by test/scipy/gen_signal2_expected.py (scipy 1.18.1).
import numpy as np
import scipy.signal as ss
import signal_spectral_expected as X

def close(x, ref, rtol: float = 1e-9, atol: float = 1e-12) -> bool:
    a = np.asarray(x).ravel()
    if a.shape[0] != len(ref):
        print('size', a.shape[0], len(ref))
        return False
    ok = True
    for i in range(len(ref)):
        if abs(a[i] - ref[i]) > atol + rtol * abs(ref[i]):
            print('mismatch', i, a[i], ref[i])
            ok = False
    return ok

@test
def test_lombscargle():
    tt = np.sort(np.mod(np.arange(60) * 0.7317, 30.0))
    yy = np.sin(1.3 * tt) + 0.4 * np.cos(3.1 * tt) + 0.2
    fr = np.linspace(0.1, 5, 40)
    assert close(ss.lombscargle(tt, yy, fr), X.ls)
    assert close(ss.lombscargle(tt, yy, fr, normalize=True), X.lsn)
    assert close(ss.lombscargle(tt, yy, fr, floating_mean=True), X.lsf)
    assert close(ss.lombscargle(tt, yy, fr, weights=np.linspace(0.5, 1.5, 60), floating_mean=True,
                                normalize=True), X.lsw)
    assert close(ss.lombscargle(tt, yy, fr, normalize='amplitude'), X.lsa)
test_lombscargle()
